package org.nonfood.oilplants.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.AuditDao;import org.nonfood.oilplants.service.PlantService;import org.nonfood.oilplants.model.Plant;import java.io.*;
@WebServlet("/admin/plants/save") public class AdminPlantSaveServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws ServletException,IOException{Plant p=new Plant();try{WebSupport.requireAdmin(r);String id=r.getParameter("id");if(id!=null&&!id.isBlank())p.setId(Long.parseLong(id));String genus=r.getParameter("genusId");if(genus!=null&&!genus.isBlank())p.setGenusId(Long.parseLong(genus));p.setNameZh(r.getParameter("nameZh"));p.setScientificName(r.getParameter("scientificName"));p.setNameEn(r.getParameter("nameEn"));p.setMorphology(r.getParameter("morphology"));p.setDistribution(r.getParameter("distribution"));p.setCultivation(r.getParameter("cultivation"));p.setUses(r.getParameter("uses"));p.setSourcePages(r.getParameter("sourcePages"));p.setVerificationStatus(r.getParameter("verificationStatus"));long plantId=new PlantService().save(p,r.getParameter("sampleLabel"),r.getParameter("oilContent"),r.getParameter("samplePages"),r.getParameter("sampleNote"),r.getParameter("components"),r.getParameter("sampleVerificationStatus"),r.getParameter("oilContentStatus"),r.getParameter("componentVerificationStatus"));new AuditDao().log(WebSupport.user(r).getId(),p.getId()>0?"UPDATE":"CREATE","plant",plantId,p.getNameZh(),r.getRemoteAddr());r.getSession().setAttribute("flash","植物资料已保存。请依据来源资料确认植物与样本的核验状态。");s.sendRedirect(r.getContextPath()+"/admin/plants/form?id="+plantId);}catch(Exception e){r.setAttribute("error",e.getMessage()==null?"保存失败，请检查字段。":e.getMessage());r.setAttribute("plant",p);r.setAttribute("sampleLabel",r.getParameter("sampleLabel"));r.setAttribute("oilContent",r.getParameter("oilContent"));r.setAttribute("samplePages",r.getParameter("samplePages"));r.setAttribute("sampleNote",r.getParameter("sampleNote"));r.setAttribute("components",r.getParameter("components"));r.setAttribute("sampleVerificationStatus",r.getParameter("sampleVerificationStatus"));r.setAttribute("oilContentStatus",r.getParameter("oilContentStatus"));r.setAttribute("componentVerificationStatus",r.getParameter("componentVerificationStatus"));try{r.setAttribute("genera",new PlantService().dao().listGenera());}catch(Exception ignored){}WebSupport.view(r,s,"admin/plant-form");}}}
